import os,json,hashlib,subprocess,tempfile,stat
from pathlib import Path
root=Path('/srv/projects/lowcost-europa')
checks={
'deploy/scripts/offsite-backup.sh':'0f63348642660c8b5b3fb04a6589dcb2c1db2ba129e51d243c432a2f7c294acc',
'deploy/scripts/offsite-restore-drill.sh':'b184ddfd10a3ee51d05bd663984728714c1259211da1dde236f0f06d0dda46ce',
'deploy/scripts/backup-postgres.sh':'d66645b4a290c65a7265d5566161570105fb9bac4edebe5e7a83e83baa843362',
'deploy/scripts/check-offsite-backup-health.sh':'da3923f23265825b92bcd33cdb5ece22e4d5299b2685ec596afbf195933ab896'}
out={'operation':'lowcost_only_canonical_code_paths','success':False,'files_changed':[],'rollbacks':[]}
old_data={}
def atomic(path,data,meta):
 fd,name=tempfile.mkstemp(prefix='.canonical-path-',dir=path.parent)
 try:
  with os.fdopen(fd,'wb') as w:
   w.write(data);w.flush();os.fsync(w.fileno())
  os.chown(name,meta.st_uid,meta.st_gid)
  os.chmod(name,stat.S_IMODE(meta.st_mode))
  if subprocess.run(['/bin/sh','-n',name],capture_output=True,timeout=8).returncode!=0:
   raise RuntimeError('script syntax validation failed')
  os.replace(name,path)
 finally:
  if os.path.exists(name):os.unlink(name)
try:
 assert root.is_dir() and not root.is_symlink()
 r=subprocess.run(['git','-c','safe.directory='+str(root),'-C',str(root),'status','--porcelain','--untracked-files=no','--',*checks.keys()],capture_output=True,text=True,timeout=12)
 assert r.returncode==0 and not r.stdout.strip(),'tracked code already dirty; not modifying'
 staged={}
 for rel,h in checks.items():
  f=root/rel
  assert f.is_file() and not f.is_symlink() and hashlib.sha256(f.read_bytes()).hexdigest()==h,'unexpected code version'
  orig=f.read_bytes()
  txt=orig.decode('utf-8')
  assert '/etc/lowcost-europa/' in txt,'legacy reference absent'
  txt=txt.replace('/etc/lowcost-europa/','/srv/projects/lowcost-europa/private/systemd-env/')
  txt=txt.replace('/var/backups/lowcost-europa/daily','/srv/projects/lowcost-europa/backups/daily')
  txt=txt.replace('/var/lib/lowcost-europa','/srv/projects/lowcost-europa/data')
  if rel.endswith('offsite-restore-drill.sh'):
   line='restored_backup_dir="$target/srv/projects/lowcost-europa/backups/daily"'
   env='restored_env="$target/srv/projects/lowcost-europa/private/systemd-env/lowcost-europa.env"'
   assert txt.count(line)==1 and txt.count(env)==1,'unexpected restore format'
   txt=txt.replace(line,line+'\nif [ ! -d "$restored_backup_dir" ]; then\n    restored_backup_dir="$target/var/backups/lowcost-europa/daily"\nfi')
   txt=txt.replace(env,env+'\nif [ ! -f "$restored_env" ]; then\n    restored_env="$target/etc/lowcost-europa/lowcost-europa.env"\nfi')
  assert txt != orig.decode('utf-8')
  assert 'R2_ENV=/etc/lowcost-europa/' not in txt and 'PASSWORD_FILE=/etc/lowcost-europa/' not in txt
  staged[rel]=(txt.encode('utf-8'),f.stat(),orig)
 for rel,(newdata,meta,orig) in staged.items():
  f=root/rel
  old_data[rel]=(orig,meta)
  atomic(f,newdata,meta)
  out['files_changed'].append(rel)
 for rel,(newdata,meta,orig) in staged.items():
  assert (root/rel).read_bytes()==newdata
 out['success']=True
 out['status']='COMPLETE'
except Exception as e:
 out.update({'status':'FAILED_ROLLBACK_ATTEMPTED','reason':type(e).__name__+': '+str(e)[:180]})
 for rel in reversed(out['files_changed']):
  try:atomic(root/rel,*old_data[rel]);out['rollbacks'].append(rel)
  except Exception as rollback:out.setdefault('rollback_errors',[]).append(type(rollback).__name__)
out['critical_services']={n:subprocess.run(['systemctl','is-active',n],capture_output=True,text=True,timeout=6).stdout.strip() for n in ('nginx','pink-iptv-backend','pink-vpn','fadego-staging','lowcost-europa','pm2-iptvpn-bot','pm2-telegram-robot-leads')}
print(json.dumps(out,separators=(',',':')))
